"""Round 100 — teaching the game and the quests (21t lessons, 21q2 journal, 21u Oswin, 21v the first walk). Run: python tests/test_round100.py [shots]"""
import sys, os, time
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from harness import game
res = []
def check(n, ok, info=''):
    res.append(bool(ok)); print(('PASS ' if ok else 'FAIL ') + n + ('' if ok else '  ' + str(info)[:500]), flush=True)
SHOTS = os.path.join(os.path.dirname(os.path.abspath(__file__)), '_shots100') if 'shots' in sys.argv else None
if SHOTS: os.makedirs(SHOTS, exist_ok=True)
def until(g, expr, ms=8000):
    t = time.time()
    while (time.time() - t) * 1000 < ms:
        if g.js(expr): return True
        g.wait(200)
    return False
def talk_through(g, n=12):
    for _ in range(n * 3):
        if not g.js("ZDLG.open"): return True
        g.page.keyboard.press('Space'); g.wait(260)
    return not g.js("ZDLG.open")
WS = "game.scene.getScene('World')"
with game(painted=True, w=1280, h=720) as g:
    g.wait(3500)
    g.js("(()=>{ ['ZLES','ZWALK','ZOSW','ZJOUR'].forEach(function(k){ window[k].on=true; }); var ws=%s, ps=ws.playerState; ws._newGame=true; delete ps.walk; ps.lessons={}; ps._lesInit=1; ps.tq={camp:0,net:0}; ps.oswin=0; ps.tracked=null; ZWALK._born=Date.now()-5000; })()" % WS)
    ok = until(g, "ZDLG.open&&!!document.querySelector('#zdlg .zd-extra')", 6000)
    check('A new game: your twin speaks first, with "I know how to play — skip the lessons" (%s)' % g.js("document.querySelector('#zdlg .zd-name')&&document.querySelector('#zdlg .zd-name').textContent"), ok and 'skip' in (g.js("document.querySelector('#zdlg .zd-extra').textContent") or ''))
    if SHOTS: g.shot(os.path.join(SHOTS, '1_twin.png'))
    talk_through(g); g.wait(700)
    a = g.js("(()=>({walk:%s.playerState.walk, line:(document.getElementById('zpath')||{}).textContent}))()" % WS)
    check('…then "walk" is the first step, in the line under the little map (%s)' % a, a['walk'] == 'move' and 'W A S D' in (a['line'] or ''), a)
    g.js("(()=>{ var p=%s.player; p.x+=TILE*4; })()" % WS); g.wait(900)
    check('Walking on moves it to the sword', g.js("%s.playerState.walk" % WS) == 'attack')
    for _ in range(3): g.page.keyboard.press('Space'); g.wait(250)
    g.wait(700); check('Three swings → "open the map"', g.js("%s.playerState.walk" % WS) == 'map')
    g.js("openWorldMap()"); g.wait(1000); g.js("(()=>{ if(typeof closeModal==='function')closeModal('map'); })()"); g.wait(700)
    b = g.js("(()=>{ var ws=%s, t=ZJOUR.target(ws); return {walk:ws.playerState.walk, t:t&&t.t}; })()" % WS)
    check('Opening the map → "go to the guild", the gold arrow pointing to it (%s)' % b, b['walk'] == 'guild' and 'Guild' in (b['t'] or ''), b)
    g.js("ZOSW.talk(%s)" % WS); g.wait(500)
    c = g.js("(()=>({name:document.querySelector('#zdlg .zd-name').textContent, text:document.querySelector('#zdlg .zd-text').textContent}))()")
    check('At the guild Master Oswin speaks — the stern scholar (%s…)' % c['text'][:40], c['name'] == 'Master Oswin', c)
    talk_through(g, 8); g.wait(800)
    d = g.js("(()=>{ var ws=%s, ps=ws.playerState, h=document.getElementById('quest-list-container').innerHTML; return {tq:ps.tq, tracked:ps.tracked, walk:ps.walk, saga:/The Saga/.test(h), side:/Side quests/.test(h), badge:(h.match(/<i>SIDE<\\/i>/g)||[]).length, accept:/qacc/.test(h), camp:/Oswin.s purse/.test(h), net:/Old Nell/.test(h), quests:document.getElementById('modal-quests').style.display!=='none'}; })()" % WS)
    check('…his two 50 g tasks given and tracked; the journal opens: the Saga + Side quests, SIDE badges, no Accept (%s)' % d, d['tq']['camp'] == 1 and d['tq']['net'] == 1 and d['tracked'] == 'tq:camp' and d['saga'] and d['side'] and d['badge'] >= 2 and not d['accept'] and d['camp'] and d['net'] and d['quests'], d)
    if SHOTS: g.shot(os.path.join(SHOTS, '2_journal.png'))
    g.js("(()=>{ if(typeof closeModal==='function')closeModal('quests'); })()"); g.wait(1200)
    check('…and coming out of the guild, the walk turns to Elder Runa', g.js("%s.playerState.walk" % WS) == 'runa')
    e = g.js("(()=>{ var ws=%s, ps=ws.playerState, g0=ps.gold||0, C=ZOSW.camp(ws); ZOSW.campDone(ws,C); return {id:C&&C.id, east:C&&C.tx>CENTER_X, gold:(ps.gold||0)-g0, camp:ps.tq.camp, tracked:ps.tracked}; })()" % WS)
    check('Oswin\'s purse: the nearest camp east of the village; beating it pays 50 g (%s)' % e, e['id'] and e['gold'] == 50 and e['camp'] == 3 and e['tracked'] == 'tq:net', e)
    g.js("(()=>{ var ws=%s, N=ZOSW.netSpot(ws); ws.player.x=N.x+TILE*0.5; ws.player.y=N.y; })()" % WS); g.wait(1800)
    f = g.js("(()=>{ var ws=%s, N=ZOSW.netSpot(ws); return {net:!!ws._tqNet, guards:(ws._tqNetG||[]).length, far:Math.round(Math.hypot(N.x/TILE-CENTER_X,N.y/TILE-CENTER_Y)), sec:getTileSection(Math.floor(N.x/TILE),Math.floor(N.y/TILE))}; })()" % WS)
    check('Old Nell\'s net lies on the lake\'s far shore, two skeletons over it (%s)' % f, f['net'] and f['guards'] == 2 and f['sec'] in (0, 1), f)
    t1 = g.js("(()=>{ var ws=%s; return ZOSW.take(ws)&&ws.playerState.tq.net; })()" % WS)
    g.js("(()=>{ (%s._tqNetG||[]).forEach(function(m){ m.dead=true; }); })()" % WS)
    t2 = g.js("(()=>{ var ws=%s; ZOSW.take(ws); return ws.playerState.tq.net; })()" % WS)
    g.js("(()=>{ var ws=%s, ps=ws.playerState; window._g0=ps.gold; ZOSW.nell(ws); })()" % WS); g.wait(300); talk_through(g)
    h = g.js("(()=>{ var ps=%s.playerState; return {net:ps.tq.net, gold:ps.gold-window._g0}; })()" % WS)
    check('Not while the skeletons stand; then Tab takes it, and Old Nell pays 50 g (%s → %s, %s)' % (t1, t2, h), t1 == 1 and t2 == 2 and h['net'] == 3 and h['gold'] == 50, h)
    g.js("(()=>{ var ws=%s, R=(ws._villageNPCs||[]).find(function(n){ return n.id==='vf_elder'; }); window._R=!!R; if(R&&R.talk)R.talk(ws); })()" % WS); g.wait(400)
    i = g.js("(()=>({R:window._R, name:ZDLG.open&&document.querySelector('#zdlg .zd-name').textContent}))()")
    talk_through(g); g.wait(600)
    j = g.js("(()=>{ var ps=%s.playerState; return {walk:ps.walk, way:!!ps.lessons.waystone}; })()" % WS)
    check('Coming out, Elder Runa shows you the runestones and the waystones; the walk is done (%s, %s)' % (i, j), i['name'] == 'Elder Runa' and j['walk'] == 'done' and j['way'], (i, j))
    g.js("(()=>{ var ps=%s.playerState; ps.lessonsOff=0; delete ps.lessons.level; ps.level=2; })()" % WS)
    ok = until(g, "ZDLG.open&&/Master Oswin/.test(document.querySelector('#zdlg .zd-name').textContent)", 4000)
    btn = g.js("[...document.querySelectorAll('#zdlg .zd-extra button')].map(b=>b.textContent)")
    check('A lesson as it comes: Oswin speaks it, the game paused, with "Don\'t show lessons" (%s)' % btn, ok and 'Don\'t show lessons' in btn and g.js("isGamePaused()"), btn)
    if SHOTS: g.shot(os.path.join(SHOTS, '3_lesson.png'))
    g.js("[...document.querySelectorAll('#zdlg .zd-extra button')].find(b=>/Don/.test(b.textContent)).click()"); g.wait(500)
    check('"Don\'t show lessons" turns them off', g.js("%s.playerState.lessonsOff==1&&!ZDLG.open" % WS))
    g.js("ZPAUSE.go('training')"); g.wait(700)
    k = g.js("(()=>{ var o=document.getElementById('modal-training'); return {shown:o&&o.style.display!=='none', items:o.querySelectorAll('.ztr-i').length, taught:o.querySelectorAll('.ztr-i:not(.q)').length, tab:!!document.querySelector('.zpz-t[data-t=training]'), ctl:!document.querySelector('.zpz-t[data-t=controls]'), box:o.querySelector('.ztr-on').checked}; })()")
    check('The Training tab (in Controls\' place): every lesson, the ones met readable, the rest ??? (%s)' % k, k['shown'] and k['items'] == 32 and k['taught'] >= 6 and k['tab'] and k['ctl'] and k['box'] is False, k)
    if SHOTS: g.shot(os.path.join(SHOTS, '4_training.png'))
    g.js("(()=>{ var c=document.querySelector('#modal-training .ztr-on'); c.checked=true; c.dispatchEvent(new Event('change')); })()")
    check('…and "Show lessons as they come" turns them back on', g.js("%s.playerState.lessonsOff==0" % WS))
    g.js("ZPAUSE.resume()"); g.wait(400)
    m = g.js("(()=>{ var ws=%s, ps=ws.playerState, L=ZJOUR.steps(ws); return {n:L.length, first:L[0].t, last:L[L.length-1].t, cur:(L.find(function(s){ return s.cur; })||{}).id, lode:L.some(function(s){ return /Lodestar/.test(s.t); }), sov:L.some(function(s){ return /Sovereign staff/.test(s.t); }), tray:L.some(function(s){ return /hearth tray/.test(s.t); })}; })()" % WS)
    check('The Saga runs to the end — the trays, the Sovereign staff, the Lodestar, the gods (%d steps)' % m['n'], m['n'] >= 30 and m['lode'] and m['sov'] and m['tray'] and 'gods' in m['last'], m)
    g.js("(()=>{ var ps=%s.playerState; ps.completedQuests=(ps.completedQuests||[]).concat(['s1_tower']); })()" % WS)
    ok = until(g, "(()=>{ var b=document.getElementById('zq-banner'); return b&&b.classList.contains('show'); })()", 3500)
    check('A Saga step done: the banner says what is next (%s)' % g.js("(document.getElementById('zq-banner')||{}).textContent"), ok)
    if SHOTS: g.shot(os.path.join(SHOTS, '5_banner.png'))
    r = g.js("(()=>{ var ws=%s; ws.playerState.oswin=3; var t=ZOSW.rumour(ws); return {t:t, n:(ws.playerState.rumours||[]).length}; })()" % WS)
    check('Oswin\'s rumour marks something unfound on the map (%s)' % (r['t'] or '')[:70], (r['t'] is None) or r['n'] >= 1, r)
    s = g.js("(()=>{ var ws=%s; ws.playerState.pathT=1300; return ZOSW.stuck(ws); })()" % WS)
    check('Stuck after 20 minutes of play without the Saga moving', s)
    lv = g.js("(()=>{ var L=ZQMAP.list(%s); return L.map(function(q){ return q.sub; }).filter(function(s){ return /Lv \\d+\\+/.test(s); }).length; })()" % WS)
    check('The suggested level stands on the map\'s quests (%s)' % lv, lv >= 1)
    E = [x for x in g.errs if '404' not in x and 'decode audio' not in x]
    check('No script errors', not E, E[:3])
print('%d / %d passed' % (sum(res), len(res)))
sys.exit(0 if all(res) else 1)
